/**
 * SEO audit of a running Hamqadam site, from what crawlers fetch: robots.txt, sitemap.xml,
 * llms.txt, the server HTML of every page in the sitemap (no JavaScript runs), the links
 * between pages, and a few indexability probes. Used by the E2E suite against the local
 * production build, and by `npm run seo:check -- <url>` against a deployment.
 *
 * The HTML is read with regular expressions: it is generated by React with a known shape,
 * and the audit must not need a browser.
 */
import { routing } from "../i18n/routing";
import { PUBLIC_PAGES, languageAlternates, localizedPath } from "../lib/seo/pages";

export type Finding = { target: string; check: string; detail: string };

export type AuditResult = {
  failures: Finding[];
  checked: { pages: number; links: number };
  pages: { url: string; title: string; description: string }[];
};

type Options = {
  /** Where to send requests, for example http://127.0.0.1:3200. */
  base: string;
  /** The origin canonical URLs must use, for example https://hamqadam.onrender.com. */
  canonicalOrigin: string;
};

const decode = (text: string) =>
  text
    .replace(/&quot;/g, '"')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");

/** Attribute values of the tags matching `tag` that have `attr`. */
function tags(html: string, tag: RegExp): Record<string, string>[] {
  return [...html.matchAll(tag)].map((match) => {
    const attributes: Record<string, string> = {};
    for (const [, name, value] of match[0].matchAll(/([a-zA-Z:-]+)="([^"]*)"/g)) {
      attributes[name!.toLowerCase()] = decode(value!);
    }
    return attributes;
  });
}

const metaTags = (html: string) => tags(html, /<meta\b[^>]*>/g);
const linkTags = (html: string) => tags(html, /<link\b[^>]*>/g);
const meta = (html: string, key: "name" | "property", value: string) =>
  metaTags(html).filter((tag) => tag[key] === value);

function jsonLdBlocks(html: string): string[] {
  return [...html.matchAll(/<script type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)].map(
    (match) => match[1]!,
  );
}

/** Visible text inside <main>, without scripts, styles or tags. */
function mainText(html: string): string {
  const main = /<main\b[^>]*>([\s\S]*?)<\/main>/.exec(html)?.[1] ?? "";
  return decode(
    main
      .replace(/<script[\s\S]*?<\/script>/g, " ")
      .replace(/<style[\s\S]*?<\/style>/g, " ")
      .replace(/<[^>]+>/g, " "),
  )
    .replace(/\s+/g, " ")
    .trim();
}

export async function auditSite({ base, canonicalOrigin }: Options): Promise<AuditResult> {
  const failures: Finding[] = [];
  const fail = (target: string, check: string, detail = "") =>
    failures.push({ target, check, detail });
  const local = (url: string) => url.replace(canonicalOrigin, base);
  const get = (path: string) => fetch(new URL(path, base), { redirect: "manual" });

  const expected = PUBLIC_PAGES.flatMap((page) =>
    routing.locales.map((locale) => `${canonicalOrigin}${localizedPath(locale, page.path)}`),
  );

  // robots.txt
  const robots = await get("/robots.txt");
  const robotsText = await robots.text();
  if (robots.status !== 200) fail("/robots.txt", "status 200", String(robots.status));
  if (!robotsText.includes(`Sitemap: ${canonicalOrigin}/sitemap.xml`))
    fail("/robots.txt", "names the canonical sitemap", robotsText);
  if (!/^Disallow: \/api\/$/m.test(robotsText)) fail("/robots.txt", "disallows /api/", robotsText);
  if (/^Disallow: \/\s*$/m.test(robotsText)) fail("/robots.txt", "does not block the whole site");

  // sitemap.xml
  const sitemap = await get("/sitemap.xml");
  const sitemapXml = await sitemap.text();
  if (sitemap.status !== 200) fail("/sitemap.xml", "status 200", String(sitemap.status));
  const locs = [...sitemapXml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((match) => decode(match[1]!));
  if (new Set(locs).size !== locs.length) fail("/sitemap.xml", "no duplicate URLs");
  if ([...locs].sort().join() !== [...expected].sort().join())
    fail("/sitemap.xml", "lists exactly the public pages", locs.join(" "));
  for (const loc of locs) {
    if (/\/(admin|api)\b|[?#]/.test(loc)) fail(loc, "sitemap URL is public and clean");
  }
  for (const url of expected) {
    const path = url.slice(canonicalOrigin.length).replace(/^\/(en|ur)/, "");
    for (const [language, alternate] of Object.entries(languageAlternates(path))) {
      const tag = `hreflang="${language}" href="${canonicalOrigin}${alternate}"`;
      if (!sitemapXml.includes(tag)) fail(url, `sitemap alternate ${language}`);
    }
  }

  // Every public page, as served.
  const pages: AuditResult["pages"] = [];
  const internalLinks = new Set<string>();
  const images = new Set<string>();
  for (const url of expected) {
    const response = await fetch(local(url), { redirect: "manual" });
    const html = await response.text();
    const locale = url.slice(canonicalOrigin.length + 1, canonicalOrigin.length + 3);
    if (response.status !== 200) {
      fail(url, "status 200", String(response.status));
      continue;
    }
    if (/noindex/i.test(response.headers.get("x-robots-tag") ?? ""))
      fail(url, "no X-Robots-Tag noindex");
    if (meta(html, "name", "robots").some((tag) => /noindex/i.test(tag["content"] ?? "")))
      fail(url, "no robots noindex meta");

    const html_ = /<html\b[^>]*>/.exec(html)?.[0] ?? "";
    if (!html_.includes(`lang="${locale}"`)) fail(url, `html lang="${locale}"`, html_);
    const dir = locale === "ur" ? "rtl" : "ltr";
    if (!html_.includes(`dir="${dir}"`)) fail(url, `html dir="${dir}"`, html_);

    const titles = [...html.matchAll(/<title>([^<]*)<\/title>/g)].map((m) => decode(m[1]!));
    const descriptions = meta(html, "name", "description").map((tag) => tag["content"] ?? "");
    if (titles.length !== 1 || !titles[0]) fail(url, "one non-empty title", titles.join(" | "));
    if (descriptions.length !== 1 || !descriptions[0])
      fail(url, "one non-empty description", descriptions.join(" | "));
    pages.push({ url, title: titles[0] ?? "", description: descriptions[0] ?? "" });

    const links = linkTags(html);
    const canonicals = links.filter((tag) => tag["rel"] === "canonical");
    if (canonicals.length !== 1 || canonicals[0]!["href"] !== url)
      fail(url, "one self-referencing canonical", canonicals.map((t) => t["href"]).join(" "));
    const alternates = Object.fromEntries(
      links
        .filter((tag) => tag["rel"] === "alternate" && tag["hreflang"])
        .map((tag) => [tag["hreflang"], tag["href"]]),
    );
    const path = url.slice(canonicalOrigin.length).replace(/^\/(en|ur)/, "");
    const expectedAlternates = Object.fromEntries(
      Object.entries(languageAlternates(path)).map(([l, p]) => [l, `${canonicalOrigin}${p}`]),
    );
    if (JSON.stringify(alternates) !== JSON.stringify(expectedAlternates))
      fail(url, "reciprocal hreflang alternates", JSON.stringify(alternates));

    const property = (name: string) => meta(html, "property", name).map((t) => t["content"]);
    const named = (name: string) => meta(html, "name", name).map((t) => t["content"]);
    if (property("og:url")[0] !== url) fail(url, "og:url is the canonical URL");
    if (property("og:title").length !== 1) fail(url, "one og:title");
    if (property("og:description")[0] !== descriptions[0]) fail(url, "og:description");
    const ogImage = property("og:image")[0] ?? "";
    if (!ogImage.startsWith(`${canonicalOrigin}/`)) fail(url, "og:image on the canonical origin");
    else images.add(ogImage);
    if (!property("og:image:alt")[0]) fail(url, "og:image:alt");
    if (property("og:locale")[0] !== (locale === "ur" ? "ur_PK" : "en_PK")) fail(url, "og:locale");
    if (named("twitter:card")[0] !== "summary_large_image") fail(url, "twitter:card");

    const blocks = jsonLdBlocks(html);
    if (blocks.length !== 1) fail(url, "one JSON-LD block", String(blocks.length));
    for (const block of blocks) {
      if (/<\/?script/i.test(block)) fail(url, "JSON-LD contains no markup");
      try {
        const data = JSON.parse(block) as { "@graph"?: Record<string, unknown>[] };
        const page = data["@graph"]?.find((node) => node["@id"] === `${url}#webpage`);
        if (!page || page["url"] !== url) fail(url, "JSON-LD describes this page");
      } catch (error) {
        fail(url, "JSON-LD parses", String(error));
      }
    }

    const h1s = html.match(/<h1\b/g)?.length ?? 0;
    if (h1s !== 1) fail(url, "one h1", String(h1s));
    if (mainText(html).length < 100) fail(url, "main content in the server HTML");
    for (const img of tags(html, /<img\b[^>]*>/g)) {
      if (!("alt" in img)) fail(url, "every image has alt text", img["src"] ?? "");
    }

    for (const [, href] of html.matchAll(/<a\b[^>]*\bhref="(\/[^"]*)"/g)) {
      internalLinks.add(decode(href!).split("#")[0]!);
    }
  }

  for (const key of ["title", "description"] as const) {
    const seen = new Map<string, string>();
    for (const page of pages) {
      const other = seen.get(page[key]);
      if (other) fail(page.url, `unique ${key}`, `same as ${other}`);
      seen.set(page[key], page.url);
    }
  }

  // The shared social images exist.
  for (const image of images) {
    const response = await fetch(local(image));
    if (response.status !== 200 || response.headers.get("content-type") !== "image/png")
      fail(image, "social image is served as PNG", String(response.status));
  }

  // Internal links lead somewhere real, without redirects.
  internalLinks.delete("");
  for (const href of internalLinks) {
    const response = await get(href);
    if (response.status !== 200) fail(href, "internal link answers 200", String(response.status));
  }

  // Indexability of everything else.
  const login = await get("/admin/login");
  if (
    !/noindex/i.test(login.headers.get("x-robots-tag") ?? "") ||
    !meta(await login.text(), "name", "robots").some((t) => /noindex/.test(t["content"] ?? ""))
  )
    fail("/admin/login", "staff sign-in is noindex (header and meta)");
  const admin = await get("/admin");
  const location = admin.headers.get("location") ?? "";
  if (
    admin.status < 300 ||
    admin.status > 399 ||
    new URL(location, base).pathname !== "/admin/login"
  )
    fail("/admin", "redirects visitors to the sign-in page", `${admin.status} ${location}`);
  if (location.includes("?")) fail("/admin", "sign-in redirect carries no parameters", location);
  const health = await get("/api/health");
  if (!/noindex/i.test(health.headers.get("x-robots-tag") ?? ""))
    fail("/api/health", "API responses are noindex");
  for (const path of ["/en/this-page-does-not-exist", "/ur/programs/no-such-program"]) {
    const missing = await get(path);
    if (missing.status !== 404) fail(path, "missing page answers 404", String(missing.status));
  }

  // llms.txt lists the public pages and nothing else.
  const llms = await get("/llms.txt");
  const llmsText = await llms.text();
  if (llms.status !== 200) fail("/llms.txt", "status 200", String(llms.status));
  const llmsLinks = [...llmsText.matchAll(/\]\(([^)]+)\)/g)].map((match) => match[1]!);
  if ([...llmsLinks].sort().join() !== [...expected].sort().join())
    fail("/llms.txt", "links exactly the public pages", llmsLinks.join(" "));

  return { failures, checked: { pages: pages.length, links: internalLinks.size }, pages };
}
